INSERT INTO `abouts` (`id`, `image`, `title`, `description`, `video_url`, `views`, `status`, `created_at`, `updated_at`) VALUES
(1, '20250602113334-image-appupnext.png', 'আমরা প্রস্তুত — আপনার ব্যবসার উন্নয়নে একসাথে এগিয়ে যেতে!', '<p data-start=\"47\" data-end=\"373\"><strong>সুন্নাহ ডিজিটাল এজেন্সি </strong>২০২০ সালে যাত্রা শুরু করে একটি স্বপ্ন নিয়ে&mdash;যেখানে শুধু ডিজিটাল মার্কেটিং সার্ভিসই নয়, বরং উদ্যোক্তা গঠনে সহায়ক একটি নির্ভরযোগ্য প্ল্যাটফর্ম হয়ে উঠবে। প্রতিষ্ঠার শুরু থেকেই আমরা বিভিন্ন ব্যবসা প্রতিষ্ঠান, স্টার্টআপ ও ব্যক্তি উদ্যোক্তাদের পাশে থেকে তাদের ডিজিটাল উপস্থিতি নিশ্চিত করতে কাজ করে যাচ্ছি।আমাদের এজেন্সি শুধু মার্কেটিং সার্ভিস প্রদানেই সীমাবদ্ধ নয়; বরং আমরা উদ্যোক্তাদের ব্যবসা শুরু থেকে পরিচালনা পর্যন্ত সব ধাপে পরামর্শ, পরিকল্পনা ও বাস্তবায়নে সার্বিক সহযোগিতা করে থাকি।</p>\r\n<p data-start=\"664\" data-end=\"924\">সুন্নাহ ডিজিটাল এজেন্সির প্রতিষ্ঠাতা, তাইফুর রহমান, গত পাঁচ বছর ধরে সফলভাবে ডিজিটাল মার্কেটিং সেক্টরে কাজ করে আসছেন। তাঁর অভিজ্ঞতা, দূরদর্শী পরিকল্পনা ও বাস্তবভিত্তিক দিকনির্দেশনা আমাদের এজেন্সিকে আরও সমৃদ্ধ করেছে এবং শত শত উদ্যোক্তার জন্য আলোর দিশা দেখিয়েছে।</p>\r\n<p data-start=\"664\" data-end=\"924\">আমরা বিশ্বাস করি, একসাথে এগিয়ে গেলে যেকোনো সাফল্য অর্জন সম্ভব। সুন্নাহ ডিজিটাল এজেন্সি আপনাকে স্বাগত জানায় এই যাত্রায় অংশগ্রহণ করতে।</p>', 'Numquam et mollit qu', '0', '1', '2024-02-27 02:44:37', '2025-06-02 05:33:34');
