INSERT INTO `teams` (`id`, `image`, `name`, `slug`, `description`, `sort_description`, `video_url`, `meta_title`, `meta_keywords`, `meta_description`, `views`, `status`, `created_at`, `updated_at`) VALUES
(1, 'taifur-rahman-appupnext.jpg', 'Taifur Rahman', 'taifur-rahman', '<div class=\"pointer-events-none h-px w-px\" aria-hidden=\"true\" data-edge=\"true\">&nbsp;</div>\r\n<article class=\"text-token-text-primary w-full sm:AIPRM__conversation__response\" dir=\"auto\" data-testid=\"conversation-turn-18\" data-scroll-anchor=\"true\">\r\n<div class=\"text-base my-auto mx-auto py-5 [--thread-content-margin:--spacing(4)] @[37rem]:[--thread-content-margin:--spacing(6)] @[72rem]:[--thread-content-margin:--spacing(16)] px-(--thread-content-margin)\">\r\n<div class=\"[--thread-content-max-width:32rem] @[34rem]:[--thread-content-max-width:40rem] @[64rem]:[--thread-content-max-width:48rem] mx-auto flex max-w-(--thread-content-max-width) flex-1 text-base gap-4 md:gap-5 lg:gap-6 group/turn-messages focus-visible:outline-hidden\" tabindex=\"-1\">\r\n<div class=\"group/conversation-turn relative flex w-full min-w-0 flex-col agent-turn\">\r\n<div class=\"relative flex-col gap-1 md:gap-3 AIPRM__conversation__response\">\r\n<div class=\"flex max-w-full flex-col grow\">\r\n<div class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal [.text-message+&amp;]:mt-5\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"9f74337a-ad32-459e-9aa8-0470aa4ccc0d\" data-message-model-slug=\"gpt-4o\">\r\n<div class=\"flex w-full flex-col gap-1 empty:hidden first:pt-[3px]\">\r\n<div class=\"markdown prose dark:prose-invert w-full break-words dark\">\r\n<p data-start=\"0\" data-end=\"195\">Hey, this is Taifur Rahman. I am a professional Facebook Ads Campaign Expert with over 5 years of experience. Over the last couple of years, I have successfully completed more than 600+ projects.</p>\r\n<p data-start=\"197\" data-end=\"414\">I am passionate and fully committed to delivering extraordinary support to my honorable clients. I strongly believe in respecting my clients\' opinions and always strive to understand and care for their business needs.</p>\r\n<p data-start=\"416\" data-end=\"622\">If you are looking for a reliable Facebook marketing solution and want to run successful Facebook Ads, feel free to send a message now. I believe in delivering premium-quality work to each and every client.</p>\r\n<p data-start=\"624\" data-end=\"642\" data-is-last-node=\"\" data-is-only-node=\"\">Thank you so much</p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"flex justify-start\">\r\n<div class=\"touch:-me-2 touch:-ms-3.5 -ms-2.5 -me-1 flex items-center p-1 select-none -mt-1 duration-[1.5s] focus-within:transition-none hover:transition-none pointer-events-none [mask-image:linear-gradient(to_right,black_33%,transparent_66%)] [mask-size:300%_100%] [mask-position:100%_0%] motion-safe:transition-[mask-position] group-hover/turn-messages:pointer-events-auto group-hover/turn-messages:[mask-position:0_0] group-focus-within/turn-messages:pointer-events-auto group-focus-within/turn-messages:[mask-position:0_0] has-data-[state=open]:pointer-events-auto has-data-[state=open]:[mask-position:0_0]\"><button class=\"text-token-text-secondary hover:bg-token-bg-secondary rounded-lg\" aria-label=\"Copy\" aria-selected=\"false\" data-testid=\"copy-turn-action-button\" data-state=\"closed\"></button><button class=\"text-token-text-secondary hover:bg-token-bg-secondary rounded-lg\" aria-label=\"Good response\" aria-selected=\"false\" data-testid=\"good-response-turn-action-button\" data-state=\"closed\"></button><button class=\"text-token-text-secondary hover:bg-token-bg-secondary rounded-lg\" aria-label=\"Bad response\" aria-selected=\"false\" data-testid=\"bad-response-turn-action-button\" data-state=\"closed\"></button><button class=\"text-token-text-secondary hover:bg-token-bg-secondary rounded-lg\" aria-label=\"Edit in canvas\" aria-selected=\"false\" data-state=\"closed\"></button>\r\n<div class=\"flex items-center\">&nbsp;</div>\r\n<span class=\"\" data-state=\"closed\"><button id=\"radix-&laquo;r7v&raqu